function nearlyMirror(s: string): boolean {
  const isMirror = (t: string) => t === t.split("").reverse().join("");
  if (isMirror(s)) return true;
  for (let k = 0; k < s.length; k++) {
    if (isMirror(s.slice(0, k) + s.slice(k + 1))) return true;
  }
  return false;
}

