function nearlyMirror(s: string): boolean {
  const isMirror = (lo: number, hi: number): boolean => {
    while (lo < hi) {
      if (s[lo] !== s[hi]) return false;
      lo++; hi--;
    }
    return true;
  };
  let i = 0, j = s.length - 1;
  while (i < j && s[i] === s[j]) { i++; j--; }
  if (i >= j) return true;
  return isMirror(i + 1, j) || isMirror(i, j - 1);
}

