class Solution:
    def nearlyMirror(self, s: str) -> bool:
        def is_mirror(lo, hi):
            while lo < hi:
                if s[lo] != s[hi]:
                    return False
                lo += 1
                hi -= 1
            return True

        i, j = 0, len(s) - 1
        while i < j and s[i] == s[j]:
            i += 1
            j -= 1
        return i >= j or is_mirror(i + 1, j) or is_mirror(i, j - 1)

